def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine aggressiveness based on whether others were bidding near/above a salary
    # and on my current HP / drought streak.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Others were very aggressive: bid moderately high but not maximal.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * 0.35
    else:
        # Others were not extreme: bid around a mid-level value; ensure survival.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.85
        else:
            # Use supply to slightly adjust: higher supply -> bid lower.
            # supply is between 15 and 25.
            supply_factor = (supply - 15.0) / (25.0 - 15.0) if 25.0 != 15.0 else 0.5
            # When supply is high, reduce bid; when low, increase.
            target = DAILY_SALARY * (0.55 - 0.25 * supply_factor)
            # Also anchor to observed bids to avoid underbidding when others compete.
            if highest_prev_bid > 0.0:
                target = max(target, min(highest_prev_bid + 2.0, DAILY_SALARY * 0.9))

    # Budget safety: never exceed budget; also cap to reasonable range.
    target = max(0.0, min(target, budget))

    # If budget is extremely low, still bid what we can.
    if budget <= 1.0:
        return budget

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_agg = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= DAILY_SALARY * 0.85 and opp.get('budget', 0) >= DAILY_SALARY:
                    rich_agg += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    slots = max(1, int(supply / WATER_REQ))
    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    critical = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if critical:
        bid = max(DAILY_SALARY * 0.96, highest_prev + 2.0)
    elif slots >= 2:
        if highest_prev >= DAILY_SALARY * 0.9:
            bid = DAILY_SALARY * 0.58 if hp > 5 else DAILY_SALARY * 0.9
        elif highest_prev > 0:
            bid = max(DAILY_SALARY * 0.62, avg_prev + 2.5)
        else:
            bid = DAILY_SALARY * 0.6
    else:
        if rich_agg >= 1:
            bid = DAILY_SALARY * 0.42 if hp > 6 else DAILY_SALARY * 0.92
        elif highest_prev > 0:
            bid = max(DAILY_SALARY * 0.7, highest_prev + 1.5)
        else:
            bid = DAILY_SALARY * 0.72

    if urgent_opp >= 2 and not critical:
        bid *= 1.06

    if pressured and highest_prev >= DAILY_SALARY * 0.8:
        bid = max(bid, DAILY_SALARY * 0.9)

    if budget < DAILY_SALARY * 1.2 and not critical:
        bid = min(bid, budget * 0.72)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)
    num_total_players = num_alive_opponents + 1 # Including myself

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    num_water_units = int(current_supply // WATER_REQ)

    yesterday_bids = []
    eric_alive = False
    eric_budget = 0
    bob_alive = False
    bob_budget = 0

    for agent_id, opp in opponents_status.items():
        if opp['alive']:
            if agent_id == "Eric":
                eric_alive = True
                eric_budget = opp['budget']
            if agent_id == "Bob":
                bob_alive = True
                bob_budget = opp['budget']

            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 1.2
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.9
    elif my_no_water_days >= 1:
        base_bid = DAILY_SALARY * 0.8
    else:
        base_bid = DAILY_SALARY * 0.6

    if num_water_units < num_total_players:
        base_bid *= 1.1
        if num_total_players - num_water_units > 1:
            base_bid *= 1.15

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            if my_hp <= 4 or my_no_water_days >= 1:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            base_bid = max(base_bid, highest_prev_bid + 2)
        else:
            base_bid = max(base_bid, highest_prev_bid * 1.1)

    if eric_alive and eric_budget > DAILY_SALARY * 5:
        if my_hp <= 4 or my_no_water_days >= 1:
            base_bid = max(base_bid, DAILY_SALARY * 1.1)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)

    if bob_alive and bob_budget > DAILY_SALARY * 2:
        if my_hp <= 4 or my_no_water_days >= 1:
            base_bid = max(base_bid, DAILY_SALARY * 1.0)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.75)

    final_bid = min(my_budget, base_bid)

    if final_bid < 1 and my_budget > 0:
        final_bid = min(my_budget, 1.0)
    elif my_budget == 0:
        final_bid = 0.0

    return float(final_bid)

